111	func (s *RSSService) GetUserRSS(c *echo.Context) error {
112		ctx := c.Request().Context()
113		username := c.Param("username")
114		cacheKey := "user:" + username
115	
116		// Check cache first
117		if cached := s.getFromCache(cacheKey); cached != nil {
118			// Check ETag for conditional request
119			if c.Request().Header.Get("If-None-Match") == cached.etag {
120				return c.NoContent(http.StatusNotModified)
121			}
122			s.setRSSHeaders(c, cached.etag, cached.lastModified)
123			return c.String(http.StatusOK, cached.content)
124		}
125	
126		user, err := s.Store.GetUser(ctx, &store.FindUser{
127			Username: &username,
128		})
129		if err != nil {
130			return echo.NewHTTPError(http.StatusInternalServerError, "Failed to find user").Wrap(err)
131		}
132		if user == nil {
133			return echo.NewHTTPError(http.StatusNotFound, "User not found")
134		}
135	
136		normalStatus := store.Normal
137		limit := maxRSSItemCount
138		memoFind := store.FindMemo{
139			CreatorID:       &user.ID,
140			RowStatus:       &normalStatus,
141			VisibilityList:  []store.Visibility{store.Public},
142			ExcludeComments: true,
143			Limit:           &limit,
144		}
145		memoList, err := s.Store.ListMemos(ctx, &memoFind)
146		if err != nil {
147			return echo.NewHTTPError(http.StatusInternalServerError, "Failed to find memo list").Wrap(err)
148		}
149	
150		baseURL := c.Scheme() + "://" + c.Request().Host
151		rss, lastModified, err := s.generateRSSFromMemoList(ctx, memoList, baseURL, user)
152		if err != nil {
153			return echo.NewHTTPError(http.StatusInternalServerError, "Failed to generate rss").Wrap(err)
154		}
155	
156		// Cache the result
157		etag := s.putInCache(cacheKey, rss, lastModified)
158		s.setRSSHeaders(c, etag, lastModified)
159		return c.String(http.StatusOK, rss)
160	}
